#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n = 0) : n(n), bit(n + 2, 0) {}

    void add(int idx, long long val) {
        for (; idx <= n; idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    long long sum(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) {
            res += bit[idx];
        }
        return res;
    }

    void range_add(int l, int r, long long val) {
        if (l > r) return;
        add(l, val);
        if (r + 1 <= n) add(r + 1, -val);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    Fenwick bitC(N), bitD(N);

    while (M--) {
        int type;
        cin >> type;

        if (type == 1) {
            int i, V;
            cin >> i >> V;

            int l = i;
            int r = min(N, i + V - 1);

            long long c = -1;
            long long d = V + i;

            bitC.range_add(l, r, c);
            bitD.range_add(l, r, d);
        } else if (type == 2) {
            int i, V;
            cin >> i >> V;

            int l = max(1, i - V + 1);
            int r = i;

            long long c = 1;
            long long d = V - i;

            bitC.range_add(l, r, c);
            bitD.range_add(l, r, d);
        } else {
            int i;
            cin >> i;

            long long ans = bitC.sum(i) * i + bitD.sum(i);
            cout << ans << '\n';
        }
    }

    return 0;
}
